# Let me try to detect filled rectangles (complete boxes)
# A box is defined by (r_min, r_max, c_min, c_max)
# It's "complete" if all four edges are filled

def has_horizontal_edge(rows, row_num, cols, start, end):
    for c in range(start, end):
        if rows[row_num][c] != 5:
            return False
    return True

def has_vertical_edge(cols, col_num, rows, start, end):
    for r in range(start, end):
        if rows[r][col_num] != 5:
            return False
    return True

def try_detect_boxes(rows, cols):
    detected = []

    # Try all possible top-left corners
    for r_min in range(rows):
        for r_max in range(r_min + 1, rows):
            for c_min in range(cols):
                for c_max in range(c_min + 1, cols):
                    # Check if this could be a box
                    if has_horizontal_edge(rows, r_min, cols, c_min, c_max + 1) and \
                       has_horizontal_edge(rows, r_max, cols, c_min, c_max + 1) and \
                       has_vertical_edge(cols, c_min, rows, r_min, r_max + 1) and \
                       has_vertical_edge(cols, c_max, rows, r_min, r_max + 1):
                        detected.append((r_min, r_max, c_min, c_max))

    return detected

# Also try one edge at a time since the grid might not have all 4 edges
def get_partial_boxes(rows, cols):
    results = []

    # Find all possible horizontal segments
    for r in range(rows):
        for c in range(cols):
            for length in range(2, cols - c + 1):
                if length > cols - c:
                    break
                seg = [(r, c + i) for i in range(length)]
                all_5 = all(rows[r][col_num] == 5 for rnum, col_num in seg)
                if all_5:
                    results.append(("horiz", r, c, length, seg))

    # Find all possible vertical segments
    for c in range(cols):
        for r in range(rows):
            for length in range(2, rows - r + 1):
                if length > rows - r:
                    break
                seg = [(rnum, c) for rnum in range(r, r + length)]
                all_5 = all(rows[rnum][col_num] == 5 for rnum, col_num in seg)
                if all_5:
                    results.append(("vert", r, c, length, seg))

    return results

# Try finding boxes after all edges are present without 4-completeness check
def find_boxes_with_trials(rows, cols):
    # A box is detected if rows have horizontal segments at min/max
    # and columns have vertical segments at min/max

    # First find all horizontal segments
    horiz_by_row = {}  # row -> list of (start, end) segments
    for r in range(rows):
        row_segs = []
        c = 0
        while c < cols:
            if rows[r][c] == 5:
                start = c
                while c < cols and rows[r][c] == 5:
                    c += 1
                end = c - 1
                if end - start + 1 >= 2:
                    row_segs.append((start, end))
            else:
                c += 1
        if row_segs:
            horiz_by_row[r] = row_segs

    # Now find overlapping vertical columns
    cols_with_h = set()
    for r in range(rows):
        for s, e in horiz_by_row.get(r, []):
            for c in range(s, e + 1):
                cols_with_h.add(c)

    # Check if these columns have continuous vertical runs
    for col in sorted(cols_with_h):
        runs = []
        r = 0
        while r < rows:
            if rows[r][col] == 5:
                start = r
                while r < rows and rows[r][col] == 5:
                    r += 1
                end = r - 1
                if end - start + 1 >= 2:
                    runs.append((start, end))
            else:
                r += 1
        if runs:
            print(f"Col {col} has vertical runs: {runs}")

    return horiz_by_row

